CREATE OR REPLACE FUNCTION public.intro_trial_offer(p_area marketplace_area)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE u uuid := auth.uid(); h text; eligible boolean; c public.intro_trial_campaigns; n integer; credits integer;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
 SELECT * INTO STRICT c FROM public.intro_trial_campaigns WHERE area = p_area;
 h := public.intro_trial_identity(u);
 credits := CASE WHEN h IS NOT NULL THEN public.account_free_posts_remaining(u) ELSE 0 END;
 eligible := h IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM public.intro_trial_identities WHERE identity_hmac = h)
  AND NOT EXISTS (SELECT 1 FROM public.intro_trial_claims WHERE user_id = u AND NOT admin_granted AND (activated_at IS NOT NULL OR (released_at IS NULL AND (content_table IS NOT NULL OR created_at > now()-interval '15 minutes'))))
  AND NOT EXISTS (SELECT 1 FROM public.free_posts_used WHERE user_id = u AND COALESCE(release_reason, '') NOT IN ('create_failed','rejected_deleted'));
 SELECT count(*) INTO n FROM public.intro_trial_claims WHERE area = p_area AND duration_days = 30 AND NOT admin_granted
  AND activated_at IS NOT NULL AND released_at IS NULL AND converted_at IS NULL AND expires_at > now();
 RETURN jsonb_build_object('adminFreePostsRemaining',credits,'eligible',eligible OR credits > 0,'sevenDayAvailable',credits = 0 AND eligible AND c.seven_day_enabled,
  'thirtyDayAvailable',credits > 0 OR (eligible AND c.launch_enabled AND n < c.slot_limit),
  'remaining',greatest(0,c.slot_limit-n),'launchEnabled',c.launch_enabled,
  'shortDays',public.intro_trial_days(7),'longDays',public.intro_trial_days(30));
END;
$function$

CREATE OR REPLACE FUNCTION public.mask_phone_public(phone_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  normalized TEXT;
  digits TEXT;
  last_two TEXT;
BEGIN
  normalized := public.normalize_sa_phone(phone_input);
  IF normalized IS NULL THEN RETURN NULL; END IF;
  digits := regexp_replace(normalized, '\\D', '', 'g');
  IF length(digits) < 4 THEN RETURN chr(8226)||chr(8226)||chr(8226)||chr(8226)||chr(8226)||chr(8226)||chr(8226)||chr(8226); END IF;
  last_two := right(digits, 2);
  IF digits LIKE '27%' THEN RETURN '+27 ' || chr(8226)||chr(8226)||chr(8226)||chr(8226) || ' ' || chr(8226)||chr(8226) || last_two; END IF;
  RETURN chr(8226)||chr(8226)||chr(8226)||chr(8226)||chr(8226) || ' ' || chr(8226)||chr(8226)||chr(8226) || last_two;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_sa_phone(phone_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  digits TEXT;
  trimmed TEXT;
BEGIN
  IF phone_input IS NULL THEN RETURN NULL; END IF;
  trimmed := btrim(phone_input);
  IF trimmed = '' THEN RETURN NULL; END IF;
  digits := regexp_replace(trimmed, '\\D', '', 'g');
  IF digits LIKE '27%' AND length(digits) = 11 THEN RETURN '+' || digits; END IF;
  IF digits LIKE '0%' AND length(digits) = 10 THEN RETURN '+27' || substr(digits, 2); END IF;
  RETURN trimmed;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_account_profile_phone_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  conflicting_profile UUID;
  phone_claim TEXT;
BEGIN
  NEW.phone := public.normalize_sa_phone(NEW.phone);
  NEW.pending_phone := public.normalize_sa_phone(NEW.pending_phone);
  NEW.masked_phone_public := public.mask_phone_public(NEW.phone);

  FOR phone_claim IN
    SELECT DISTINCT claim
    FROM unnest(ARRAY[NEW.phone, NEW.pending_phone]) AS phone_claims(claim)
    WHERE claim IS NOT NULL
    ORDER BY claim
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(phone_claim, 0));
  END LOOP;

  IF NEW.phone IS NOT NULL THEN
    SELECT ap.id
    INTO conflicting_profile
    FROM public.account_profiles ap
    WHERE ap.id IS DISTINCT FROM NEW.id
      AND (ap.phone = NEW.phone OR ap.pending_phone = NEW.phone)
    LIMIT 1;

    IF conflicting_profile IS NOT NULL THEN
      RAISE EXCEPTION 'Phone number already linked to another account'
        USING ERRCODE = '23505',
              CONSTRAINT = 'account_profiles_phone_unique';
    END IF;
  END IF;

  IF NEW.pending_phone IS NOT NULL THEN
    SELECT ap.id
    INTO conflicting_profile
    FROM public.account_profiles ap
    WHERE ap.id IS DISTINCT FROM NEW.id
      AND (ap.phone = NEW.pending_phone OR ap.pending_phone = NEW.pending_phone)
    LIMIT 1;

    IF conflicting_profile IS NOT NULL THEN
      RAISE EXCEPTION 'Phone number already linked to another account'
        USING ERRCODE = '23505',
              CONSTRAINT = 'account_profiles_pending_phone_unique';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_seller_profile_phone_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  NEW.phone := public.normalize_sa_phone(NEW.phone);
  NEW.masked_phone_public := public.mask_phone_public(NEW.phone);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_listing_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text := OLD.status::text; n text := NEW.status::text;
BEGIN
 IF o = n THEN RETURN NEW; END IF;
 IF NOT (auth.role() IS NULL OR auth.role() = 'service_role' OR public.has_role('admin')) THEN
  IF NOT ((o = 'draft' AND n = 'pending_moderation') OR (o = 'live' AND n IN ('hidden','sold'))) THEN
   RAISE EXCEPTION 'Status transition % → % requires moderation privileges', o, n USING ERRCODE = 'insufficient_privilege';
  END IF;
 END IF;
 IF NOT (
  (o = 'draft' AND n = 'pending_moderation') OR
  (o = 'pending_moderation' AND n IN ('live','rejected','flagged_for_review','hidden')) OR
  (o = 'flagged_for_review' AND n IN ('live','rejected','hidden','pending_moderation','suspended')) OR
  (o = 'live' AND n IN ('hidden','expired','flagged_for_review','sold','suspended')) OR
  (o = 'hidden' AND n IN ('live','pending_moderation','rejected','archived')) OR
  -- Reactivation of unchanged approved content after payment is a system write.
  (o = 'expired' AND n IN ('pending_moderation','draft','live','archived')) OR
  (o = 'sold' AND n IN ('live','pending_moderation','archived')) OR
  (o = 'suspended' AND n IN ('live','hidden','rejected','archived')) OR
  (o = 'archived' AND n IN ('draft','pending_moderation')) OR
  (o = 'rejected' AND n IN ('pending_moderation','draft','archived'))
 ) THEN
  RAISE EXCEPTION 'Invalid status transition: % → %', o, n USING ERRCODE = 'check_violation';
 END IF;
 RETURN NEW;
END;
$function$

