CREATE OR REPLACE FUNCTION public.guard_post_funding_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE field text;
BEGIN
 IF auth.role() IS NULL OR auth.role() = 'service_role' THEN RETURN NEW; END IF;
 IF TG_OP = 'INSERT' THEN
  IF NEW.status = 'live' THEN RAISE EXCEPTION 'Publication requires moderation' USING ERRCODE='42501'; END IF;
 ELSE
  IF NEW.status = 'live' AND OLD.status <> 'live' THEN
   RAISE EXCEPTION 'Publication requires moderation' USING ERRCODE='42501';
  END IF;
  FOREACH field IN ARRAY ARRAY['owner_id','area','created_at','published_at','expires_at','featured','urgent'] LOOP
   IF to_jsonb(NEW)->field IS DISTINCT FROM to_jsonb(OLD)->field THEN
    RAISE EXCEPTION 'Funding fields require a system workflow' USING ERRCODE='42501';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_business_verification_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  verification_cols text[] := ARRAY[
    'cipc_verified_at', 'cipc_expires_at', 'cipc_registration_number', 'cipc_registered_name',
    'cipc_registered_office', 'show_full_registered_office', 'seen_verified_at',
    'seen_expires_at', 'seen_method', 'seen_city', 'owner_verified_role', 'owner_position_title'];
  col text;
BEGIN
  -- A new owner does not inherit the previous owner's verification.
  IF TG_OP = 'UPDATE' AND NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    NEW.cipc_verified_at := NULL; NEW.cipc_expires_at := NULL;
    NEW.cipc_registration_number := NULL; NEW.cipc_registered_name := NULL;
    NEW.cipc_registered_office := NULL; NEW.show_full_registered_office := false;
    NEW.seen_verified_at := NULL; NEW.seen_expires_at := NULL;
    NEW.seen_method := NULL; NEW.seen_city := NULL;
    NEW.owner_verified_role := NULL; NEW.owner_position_title := NULL;
    -- Profiles linked to this company share its sticker, so they lose it too.
    WITH links AS (
      UPDATE public.business_verifications l
         SET status = 'revoked', reason_code = 'source_owner_changed', decided_at = now()
       WHERE l.kind = 'cipc_link' AND l.status = 'approved' AND l.business_id <> NEW.id
         AND l.linked_case_id IN (SELECT c.id FROM public.business_verifications c
                                   WHERE c.business_id = NEW.id)
      RETURNING l.business_id
    )
    UPDATE public.businesses b
       SET cipc_verified_at = NULL, cipc_expires_at = NULL, cipc_registration_number = NULL,
           cipc_registered_name = NULL, cipc_registered_office = NULL,
           show_full_registered_office = false, owner_verified_role = NULL,
           owner_position_title = NULL
     WHERE b.id IN (SELECT business_id FROM links);
    UPDATE public.business_verifications
       SET status = 'revoked', reason_code = 'ownership_changed', decided_at = now()
      WHERE business_id = NEW.id AND status IN ('approved', 'pending', 'info_requested');
    RETURN NEW;
  END IF;

  IF auth.role() IS NULL OR auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  FOREACH col IN ARRAY verification_cols LOOP
    IF TG_OP = 'INSERT' THEN
      IF to_jsonb(NEW) -> col IS NOT NULL AND to_jsonb(NEW) -> col <> 'null'::jsonb
         AND NOT (col = 'show_full_registered_office' AND to_jsonb(NEW) -> col = 'false'::jsonb) THEN
        RAISE EXCEPTION 'Verification fields are set by VerifyMzansi staff'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSIF to_jsonb(NEW) -> col IS DISTINCT FROM to_jsonb(OLD) -> col THEN
      RAISE EXCEPTION 'Verification fields are set by VerifyMzansi staff'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_content_monetization_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  protected_column TEXT;
  old_json JSONB := to_jsonb(OLD);
  new_json JSONB := to_jsonb(NEW);
BEGIN
  IF auth.role() IS NULL OR auth.role() = 'service_role' OR public.has_role('admin') THEN
    RETURN NEW;
  END IF;

  FOREACH protected_column IN ARRAY ARRAY[
    'boost_until',
    'featured_until',
    'urgent_until',
    'view_count',
    'click_count',
    'approved_edit_count'
  ]
  LOOP
    IF (old_json ? protected_column)
       AND (new_json ? protected_column)
       AND new_json->protected_column IS DISTINCT FROM old_json->protected_column THEN
      RAISE EXCEPTION '% can only be changed by billing or system workflows', protected_column
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_content_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.account_profiles ap
              WHERE ap.user_id = OLD.owner_id AND ap.legal_hold) THEN
    RAISE EXCEPTION 'content_under_legal_hold' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF auth.role() = 'authenticated' AND NOT public.has_role('admin')
     AND OLD.status::text IN ('suspended', 'flagged_for_review') THEN
    RAISE EXCEPTION 'content_under_review' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_owner_content_edits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  -- Bookkeeping and presentation-only fields (image crop and dimensions).
  review_exempt text[] := ARRAY['status', 'updated_at', 'search_vector', 'edited_since_review',
                                'focal_x', 'focal_y', 'media_width', 'media_height'];
  content_changed boolean :=
    (to_jsonb(NEW) - review_exempt) IS DISTINCT FROM (to_jsonb(OLD) - review_exempt);
BEGIN
  IF auth.role() IS NULL OR auth.role() = 'service_role' OR public.has_role('admin') THEN
    -- Moderation approval clears the flag; nothing else touches it.
    IF NEW.status::text = 'live'
       AND OLD.status::text IN ('pending_moderation', 'flagged_for_review') THEN
      NEW.edited_since_review := false;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.edited_since_review IS DISTINCT FROM OLD.edited_since_review
     OR to_jsonb(NEW)->'entitlement_id' IS DISTINCT FROM to_jsonb(OLD)->'entitlement_id'
     OR to_jsonb(NEW)->'status_reason' IS DISTINCT FROM to_jsonb(OLD)->'status_reason' THEN
    RAISE EXCEPTION 'edited_since_review, entitlement_id and status_reason are set by system workflows'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF content_changed THEN
    -- Approved content changes only through the content edit review. Status
    -- moves (hide, mark sold) stay subject to validate_listing_status_transition.
    IF OLD.status::text = 'live' THEN
      RAISE EXCEPTION 'Live content changes must go through edit review'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    -- Content under suspension or review is evidence: it can't be rewritten.
    IF OLD.status::text IN ('suspended', 'flagged_for_review') THEN
      RAISE EXCEPTION 'Content under review or suspension cannot be edited'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status::text NOT IN ('draft', 'pending_moderation', 'rejected') THEN
      NEW.edited_since_review := true;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_intro_trial_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE t public.intro_trial_claims; c public.intro_trial_campaigns; h text; n integer;
 a public.marketplace_area; staff boolean; event_end timestamptz; e public.slot_entitlements; is_event boolean;
BEGIN
 IF TG_OP = 'UPDATE' AND
  (to_jsonb(NEW) - ARRAY['view_count','click_count','updated_at']) =
  (to_jsonb(OLD) - ARRAY['view_count','click_count','updated_at']) THEN RETURN NEW; END IF;
 IF TG_OP = 'DELETE' THEN
  SELECT * INTO t FROM public.intro_trial_claims WHERE content_id = OLD.id FOR UPDATE;
  IF t.id IS NOT NULL THEN UPDATE public.intro_trial_claims SET released_at = COALESCE(released_at,now()), release_reason = 'content_deleted' WHERE id = t.id; END IF;
  PERFORM public.release_content_slot(OLD.id,'deleted');
  RETURN OLD;
 END IF;
 SELECT * INTO t FROM public.intro_trial_claims WHERE content_id = NEW.id FOR UPDATE;
 a := CASE WHEN TG_TABLE_NAME = 'promotions' THEN 'PROMOTIONS_EVENTS'::public.marketplace_area ELSE (to_jsonb(NEW)->>'area')::public.marketplace_area END;
 event_end := (to_jsonb(NEW)->>'end_date')::timestamptz;
 is_event := TG_TABLE_NAME = 'promotions' AND to_jsonb(NEW)->>'promotion_type' = 'event';
 IF t.id IS NOT NULL THEN
  IF t.user_id IS DISTINCT FROM NEW.owner_id OR t.area IS DISTINCT FROM a THEN RAISE EXCEPTION 'Trial ownership or area mismatch'; END IF;
  UPDATE public.intro_trial_claims SET content_table = TG_TABLE_NAME WHERE id = t.id;
 END IF;
 IF NEW.status::text <> 'live' THEN
  IF t.id IS NOT NULL AND NEW.status::text IN ('hidden','expired','rejected','flagged_for_review','sold','suspended','archived') THEN
   UPDATE public.intro_trial_claims SET released_at = COALESCE(released_at,now()), release_reason = NEW.status::text WHERE id = t.id;
  END IF;
  -- A slot is held through review of already-live content; any take-down frees it.
  IF NEW.status::text IN ('hidden','expired','rejected','sold','suspended','archived') THEN
   PERFORM public.release_content_slot(NEW.id, NEW.status::text);
  END IF;
  RETURN NEW;
 END IF;
 IF t.id IS NULL AND TG_OP = 'UPDATE' AND OLD.status::text = 'live' THEN RETURN NEW; END IF;
 SELECT COALESCE(public.staff_role_of(auth.users.id),'') IN ('admin','governance_controller','moderator') INTO staff FROM auth.users WHERE id = NEW.owner_id;
 IF staff THEN
  IF t.id IS NOT NULL THEN UPDATE public.intro_trial_claims SET released_at = COALESCE(released_at,now()), release_reason = 'staff_bypass' WHERE id = t.id; END IF;
  RETURN NEW;
 END IF;

 -- Events are free and never consume trials or paid slots; fair use applies.
 IF is_event THEN
  IF t.id IS NOT NULL THEN UPDATE public.intro_trial_claims SET released_at = COALESCE(released_at,now()), release_reason = 'free_event' WHERE id = t.id; END IF;
  SELECT count(*) INTO n FROM public.promotions p WHERE p.owner_id = NEW.owner_id AND p.id <> NEW.id AND p.status = 'live'
   AND to_jsonb(p)->>'promotion_type' = 'event' AND (p.expires_at IS NULL OR p.expires_at > now());
  IF n >= (public.event_limits(NEW.owner_id)->>'maxActive')::integer THEN
   RAISE EXCEPTION 'EVENT_LIMIT: Maximum active events reached for this account';
  END IF;
  NEW.expires_at := COALESCE(event_end, now() + make_interval(days => public.commercial_setting_int('events','defaultVisibilityDays',30)));
  IF NEW.expires_at <= now() THEN RAISE EXCEPTION 'TRIAL_EVENT_ENDED: Event has already ended'; END IF;
  RETURN NEW;
 END IF;

 -- Paid, programme and sponsored visibility: activate a reusable slot.
 IF t.id IS NULL OR t.converted_at IS NOT NULL THEN
  e := public.activate_content_slot(TG_TABLE_NAME, NEW.id, NEW.owner_id, a);
  IF e.id IS NULL THEN
   IF t.id IS NULL AND EXISTS (SELECT 1 FROM public.free_posts_used WHERE user_id = NEW.owner_id AND content_id = NEW.id AND released_at IS NULL) THEN
    RETURN NEW;
   END IF;
   IF t.id IS NULL THEN RAISE EXCEPTION 'TRIAL_REQUIRED: Select an introductory offer or a paid plan'; END IF;
   RAISE EXCEPTION 'TRIAL_EXPIRED: Paid renewal required';
  END IF;
  NEW.expires_at := e.expires_at;
  IF event_end IS NOT NULL THEN
   NEW.expires_at := least(NEW.expires_at,event_end);
   IF NEW.expires_at <= now() THEN RAISE EXCEPTION 'TRIAL_EVENT_ENDED: Event has already ended'; END IF;
  END IF;
  RETURN NEW;
 END IF;

 h := public.intro_trial_identity(NEW.owner_id);
 IF h IS NULL THEN RAISE EXCEPTION 'TRIAL_VERIFICATION_REQUIRED: Complete verification before approval'; END IF;
 IF t.activated_at IS NOT NULL THEN
  IF t.released_at IS NOT NULL OR t.expires_at <= now() THEN RAISE EXCEPTION 'TRIAL_EXPIRED: Paid renewal required'; END IF;
  NEW.expires_at := t.expires_at;
 ELSE
  IF t.released_at IS NOT NULL THEN RAISE EXCEPTION 'TRIAL_RELEASED: Select a new offer'; END IF;
  IF NOT t.admin_granted THEN
   PERFORM pg_advisory_xact_lock(hashtext(h || '::intro_identity'));
   IF EXISTS (SELECT 1 FROM public.intro_trial_identities WHERE identity_hmac = h) THEN RAISE EXCEPTION 'TRIAL_USED: Introductory offer already used'; END IF;
   SELECT * INTO STRICT c FROM public.intro_trial_campaigns WHERE area = a FOR UPDATE;
   IF (t.duration_days = 7 AND NOT c.seven_day_enabled) OR (t.duration_days = 30 AND NOT c.launch_enabled) THEN RAISE EXCEPTION 'TRIAL_PAUSED: Campaign is paused; post remains pending'; END IF;
   IF t.duration_days = 30 THEN
    SELECT count(*) INTO n FROM public.intro_trial_claims WHERE area = a AND duration_days = 30 AND NOT admin_granted
     AND activated_at IS NOT NULL AND released_at IS NULL AND converted_at IS NULL AND expires_at > now();
    IF n >= c.slot_limit THEN RAISE EXCEPTION 'TRIAL_FULL: No 30-day slot available; post remains pending'; END IF;
   END IF;
  END IF;
  NEW.expires_at := now() + make_interval(days => CASE WHEN t.admin_granted THEN 30 ELSE public.intro_trial_days(t.duration_days) END);
  IF TG_TABLE_NAME = 'promotions' AND event_end IS NOT NULL THEN NEW.expires_at := least(NEW.expires_at,event_end); END IF;
  IF NEW.expires_at <= now() THEN RAISE EXCEPTION 'TRIAL_EVENT_ENDED: Event has already ended'; END IF;
  IF NOT t.admin_granted THEN
   INSERT INTO public.intro_trial_identities(identity_hmac,programme_kind,user_id)
   VALUES (h,CASE WHEN t.duration_days = 30 THEN 'PUBLIC_30_DAY' ELSE 'PUBLIC_7_DAY' END,NEW.owner_id);
  END IF;
  UPDATE public.intro_trial_claims SET activated_at = now(), expires_at = NEW.expires_at WHERE id = t.id;
  INSERT INTO public.notifications(user_id,type,title,message,href)
   VALUES (NEW.owner_id,'success',CASE WHEN t.admin_granted THEN 'Your free post is active' ELSE 'Your introductory trial is active' END,
    'Your post is visible until ' || to_char(NEW.expires_at AT TIME ZONE 'Africa/Johannesburg','DD Mon YYYY HH24:MI') || ' SAST. Renew from R50 to keep it active.','/dashboard/listings');
 END IF;
 NEW := jsonb_populate_record(NEW, jsonb_build_object('boost_until',NULL,'featured_until',NULL,'urgent_until',NULL,'featured',false,'urgent',false));
 IF TG_TABLE_NAME = 'promotions' AND event_end IS NOT NULL THEN
  NEW.expires_at := least(NEW.expires_at,event_end);
  UPDATE public.intro_trial_claims SET expires_at = NEW.expires_at WHERE id = t.id;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.one_cipc_holder_per_company()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.cipc_registration_number IS NULL OR NEW.cipc_verified_at IS NULL THEN
    RETURN NEW;
  END IF;
  -- Serialise grants for the same company so two approvals can't both pass.
  PERFORM pg_advisory_xact_lock(hashtext('cipc_holder:' || NEW.cipc_registration_number));
  IF EXISTS (SELECT 1 FROM public.businesses b
              WHERE b.cipc_registration_number = NEW.cipc_registration_number
                AND b.cipc_verified_at IS NOT NULL
                AND b.owner_id IS DISTINCT FROM NEW.owner_id
                AND b.id <> NEW.id) THEN
    RAISE EXCEPTION 'cipc_held_by_other_owner' USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_private_post_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  priv text := CASE TG_TABLE_NAME WHEN 'businesses' THEN 'business_private' ELSE 'listing_private' END;
  fk text := CASE TG_TABLE_NAME WHEN 'businesses' THEN 'business_id' ELSE 'listing_id' END;
  rec jsonb := to_jsonb(NEW);
  cleared jsonb := '{}'::jsonb;
  col text;
BEGIN
  FOREACH col IN ARRAY TG_ARGV LOOP
    cleared := cleared || jsonb_build_object(col, NULL);
    IF TG_OP = 'INSERT' AND rec->>col IS NULL THEN
      CONTINUE;
    END IF;
    EXECUTE format(
      'INSERT INTO public.%1$I (%2$I, %3$I) VALUES ($1, $2)
